content:
mFcs           = kInitFcs;
                break;

            default:
                if (mWritePointer.CanWrite(sizeof(uint8_t)))
                {
                    mFcs = UpdateFcs(mFcs, byte);
                    mWritePointer.WriteByte(byte);
                    mDecodedLength++;
                }
                else
                {
                    mFrameHandler(mContext, OT_ERROR_NO_BUFS);
                    mState = kStateNoSync;
                }

